package com.eduflow.backend;

import com.eduflow.backend.entity.*;
import com.eduflow.backend.repository.*;
import com.eduflow.backend.security.JwtService;
import com.eduflow.backend.service.*;
import com.fasterxml.jackson.databind.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc
class AttendanceManagementTests {
    @Autowired MockMvc mvc;@Autowired ObjectMapper mapper;@Autowired JwtService jwt;
    @Autowired AttendanceSessionRepository sessions;@Autowired AttendanceRecordRepository records;
    @Autowired CourseRepository courses;@Autowired BatchRepository batches;@Autowired BatchTeacherAssignmentRepository assignments;
    @Autowired BatchScheduleRepository schedules;@Autowired BatchEnrollmentRepository enrollments;
    @Autowired TeacherRepository teachers;@Autowired StudentRepository students;@Autowired UserRepository users;
    String admin,teacherToken,otherTeacher,studentToken,parent;Long batchId,courseId;Teacher teacher;List<Student> cohort;
    LocalDate today=BatchService.today();
    @BeforeEach void setup() {
        clean();users.saveAndFlush(new User("Admin","admin@attendance.test","unused",Role.ADMIN));
        User tu=users.saveAndFlush(new User("Teacher","teacher@attendance.test","unused",Role.TEACHER));
        users.saveAndFlush(new User("Unassigned","other@attendance.test","unused",Role.TEACHER));
        User su=users.saveAndFlush(new User("Student","student@attendance.test","unused",Role.STUDENT));
        users.saveAndFlush(new User("Parent","parent@attendance.test","unused",Role.PARENT));
        admin=jwt.generateToken("admin@attendance.test");teacherToken=jwt.generateToken(tu.getEmail());otherTeacher=jwt.generateToken("other@attendance.test");studentToken=jwt.generateToken(su.getEmail());parent=jwt.generateToken("parent@attendance.test");
        Course c=new Course();c.setCode("ATT");c.setName("Attendance course");c.setDurationWeeks(10);courses.saveAndFlush(c);courseId=c.getId();
        batchId=makeBatch("B1");teacher=new Teacher();teacher.setEmployeeId("T-1");teacher.setFullName("Teacher");teacher.setEmail("faculty@attendance.test");teacher.setUser(tu);teachers.saveAndFlush(teacher);
        BatchTeacherAssignment a=new BatchTeacherAssignment();a.setBatch(batches.findById(batchId).orElseThrow());a.setTeacher(teacher);assignments.saveAndFlush(a);
        cohort=new ArrayList<>();for(int i=0;i<4;i++){Student s=new Student("ATT-"+i);s.setFullName("Student "+i);s.setEmail("student"+i+"@attendance.test");s.setPhone("9876543210");s.setDateOfBirth(today.minusYears(18));s.setAdmissionDate(today.minusMonths(2));s.setAddress("Address");s.setGuardianName("Guardian");s.setGuardianPhone("9876543211");if(i==0)s.setUser(su);students.saveAndFlush(s);cohort.add(s);enroll(batchId,s,today.minusDays(5));}
    }
    @AfterEach void clean(){records.deleteAll();sessions.deleteAll();schedules.deleteAll();assignments.deleteAll();enrollments.deleteAll();batches.deleteAll();courses.deleteAll();teachers.deleteAll();students.deleteAll();users.deleteAll();}
    Long makeBatch(String code){Batch b=new Batch();b.setCode(code);b.setName(code);b.setCourse(courses.findById(courseId).orElseThrow());b.setCapacity(10);b.setStartDate(today.minusDays(20));b.setEndDate(today.plusDays(20));b.setStatus(BatchStatus.ACTIVE);return batches.saveAndFlush(b).getId();}
    void enroll(Long b,Student s,LocalDate date){var e=new BatchEnrollment();e.setBatch(batches.findById(b).orElseThrow());e.setStudent(s);e.setEnrollmentDate(date);enrollments.saveAndFlush(e);}
    MockHttpServletRequestBuilder json(MockHttpServletRequestBuilder r,Object body,String token)throws Exception{return r.header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(body));}
    JsonNode body(String value)throws Exception{return mapper.readTree(value);}
    JsonNode create(Long b,LocalDate date,String time,String token)throws Exception {var input=new HashMap<String,Object>();input.put("batchId",b);input.put("sessionDate",date.toString());if(time!=null){input.put("startTime",time);input.put("endTime",LocalTime.parse(time).plusHours(1).toString());}return body(mvc.perform(json(post("/api/attendance/sessions"),input,token)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());}
    long id(JsonNode data){return data.get("session").get("id").asLong();}
    long version(Long id)throws Exception{return body(mvc.perform(get("/api/attendance/sessions/"+id).header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()).get("session").get("version").asLong();}
    List<Map<String,Object>> marks(String...statuses){List<Map<String,Object>> list=new ArrayList<>();for(int i=0;i<statuses.length;i++)list.add(Map.of("studentId",cohort.get(i).getId(),"status",statuses[i],"remarks",""));return list;}
    JsonNode save(Long id,List<Map<String,Object>> list)throws Exception{return body(mvc.perform(json(put("/api/attendance/sessions/"+id+"/records"),Map.of("version",version(id),"records",list),admin)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
    void finish(Long id)throws Exception{mvc.perform(json(post("/api/attendance/sessions/"+id+"/finalize"),Map.of("version",version(id)),admin)).andExpect(status().isOk());}
    @Test void createsForAdminAndAssignedTeacherWithNoAutomaticMarks()throws Exception{var a=create(batchId,today,"09:00",admin);assertThat(a.get("students")).hasSize(4);assertThat(a.get("students").get(0).get("status").isNull()).isTrue();assertThat(a.get("session").get("markedCount").asInt()).isZero();create(batchId,today,"10:00",teacherToken);assertThat(records.count()).isZero();}
    @Test void occurrenceUniquenessIncludesScheduledAndManualClasses()throws Exception{var s=new BatchSchedule();s.setBatch(batches.findById(batchId).orElseThrow());s.setTeacher(teacher);s.setDayOfWeek(today.getDayOfWeek());s.setStartTime(LocalTime.of(9,0));s.setEndTime(LocalTime.of(10,0));schedules.saveAndFlush(s);mvc.perform(json(post("/api/attendance/sessions"),Map.of("batchId",batchId,"sessionDate",today.toString(),"scheduleId",s.getId()),admin)).andExpect(status().isCreated());mvc.perform(json(post("/api/attendance/sessions"),Map.of("batchId",batchId,"sessionDate",today.toString(),"startTime","09:00","endTime","11:00"),admin)).andExpect(status().isConflict());create(batchId,today,"11:00",admin);create(batchId,today,null,admin);mvc.perform(json(post("/api/attendance/sessions"),Map.of("batchId",batchId,"sessionDate",today.toString()),admin)).andExpect(status().isConflict());}
    @Test void validatesDatesScheduleWeekdayAndTerminalBatch()throws Exception{mvc.perform(json(post("/api/attendance/sessions"),Map.of("batchId",batchId,"sessionDate",today.minusDays(30).toString()),admin)).andExpect(status().isBadRequest());var s=new BatchSchedule();s.setBatch(batches.findById(batchId).orElseThrow());s.setTeacher(teacher);s.setDayOfWeek(today.plusDays(1).getDayOfWeek());s.setStartTime(LocalTime.of(9,0));s.setEndTime(LocalTime.of(10,0));schedules.saveAndFlush(s);mvc.perform(json(post("/api/attendance/sessions"),Map.of("batchId",batchId,"sessionDate",today.toString(),"scheduleId",s.getId()),admin)).andExpect(status().isBadRequest());var b=batches.findById(batchId).orElseThrow();b.setStatus(BatchStatus.CANCELLED);batches.saveAndFlush(b);mvc.perform(json(post("/api/attendance/sessions"),Map.of("batchId",batchId,"sessionDate",today.toString()),admin)).andExpect(status().isConflict());}
    @Test void bulkSubmissionAtomicAndDuplicateStudentsRejected()throws Exception{Long id=id(create(batchId,today,null,admin));save(id,marks("PRESENT"));long version=version(id);var invalid=new ArrayList<>(marks("ABSENT","LATE"));invalid.add(Map.of("studentId",999999,"status","PRESENT"));mvc.perform(json(put("/api/attendance/sessions/"+id+"/records"),Map.of("version",version,"records",invalid),admin)).andExpect(status().isBadRequest());assertThat(records.count()).isEqualTo(1);assertThat(records.findAll().getFirst().getStatus()).isEqualTo(AttendanceStatus.PRESENT);mvc.perform(json(put("/api/attendance/sessions/"+id+"/records"),Map.of("version",version,"records",List.of(marks("PRESENT").getFirst(),marks("PRESENT").getFirst())),admin)).andExpect(status().isBadRequest());assertThat(records.count()).isEqualTo(1);}
    @Test void validatesStatusAndVersionAndAllowsDraftEditingClearing()throws Exception{Long id=id(create(batchId,today,null,admin));save(id,marks("PRESENT"));mvc.perform(json(put("/api/attendance/sessions/"+id+"/records"),Map.of("version",0,"records",marks("ABSENT")),admin)).andExpect(status().isConflict());save(id,marks("ABSENT"));assertThat(records.findAll().getFirst().getStatus()).isEqualTo(AttendanceStatus.ABSENT);mvc.perform(json(put("/api/attendance/sessions/"+id+"/records"),Map.of("version",version(id),"records",List.of(Map.of("studentId",cohort.getFirst().getId(),"status","NOT_MARKED"))),admin)).andExpect(status().isBadRequest());save(id,List.of());assertThat(records.count()).isZero();}
    @Test void incompleteRegisterCannotFinalizeAndFinalizedIsImmutable()throws Exception{Long id=id(create(batchId,today,null,admin));save(id,marks("PRESENT"));mvc.perform(post("/api/attendance/sessions/"+id+"/finalize").header("Authorization","Bearer "+admin)).andExpect(status().isConflict());save(id,marks("PRESENT","LATE","ABSENT","EXCUSED"));finish(id);mvc.perform(json(put("/api/attendance/sessions/"+id+"/records"),Map.of("version",version(id),"records",List.of()),admin)).andExpect(status().isConflict());mvc.perform(post("/api/attendance/sessions/"+id+"/finalize").header("Authorization","Bearer "+admin)).andExpect(status().isConflict());assertThat(records.count()).isEqualTo(4);}
    @Test void futureSessionCannotFinalize()throws Exception{Long id=id(create(batchId,today.plusDays(1),null,admin));save(id,marks("PRESENT","PRESENT","PRESENT","PRESENT"));mvc.perform(post("/api/attendance/sessions/"+id+"/finalize").header("Authorization","Bearer "+teacherToken)).andExpect(status().isBadRequest());}
    @Test void percentagesUseFinalizedRecordsAndExcludeExcusedAndDrafts()throws Exception{Long id=id(create(batchId,today,null,admin));save(id,marks("PRESENT","LATE","ABSENT","EXCUSED"));finish(id);Long draft=id(create(batchId,today,"12:00",admin));save(draft,marks("ABSENT","ABSENT","ABSENT","ABSENT"));mvc.perform(get("/api/attendance/reports").header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andExpect(jsonPath("totals.attendancePercentage").value(66.67)).andExpect(jsonPath("totals.presentCount").value(1)).andExpect(jsonPath("totals.lateCount").value(1)).andExpect(jsonPath("totals.absentCount").value(1)).andExpect(jsonPath("totals.excusedCount").value(1)).andExpect(jsonPath("totals.totalEligibleFinalizedSessions").value(4)).andExpect(jsonPath("totals.finalizedSessions").value(1));}
    @Test void noDataAndExcusedOnlyAreNullNotZero()throws Exception{mvc.perform(get("/api/attendance/me").header("Authorization","Bearer "+studentToken)).andExpect(status().isOk()).andExpect(jsonPath("totals.attendancePercentage").isEmpty());Long id=id(create(batchId,today,null,admin));save(id,marks("EXCUSED","EXCUSED","EXCUSED","EXCUSED"));finish(id);mvc.perform(get("/api/attendance/reports").header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andExpect(jsonPath("totals.attendancePercentage").isEmpty()).andExpect(jsonPath("totals.excusedCount").value(4));}
    @Test void preEnrollmentClassesDoNotCountAndEmptyFinalizedSessionStillCountsAsClass()throws Exception{Long id=id(create(batchId,today.minusDays(10),null,admin));finish(id);assertThat(records.count()).isZero();mvc.perform(get("/api/attendance/overview").header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andExpect(jsonPath("totals.totalEligibleFinalizedSessions").value(0)).andExpect(jsonPath("totals.finalizedSessions").value(1)).andExpect(jsonPath("totals.attendancePercentage").isEmpty());}
    @Test void withdrawalDoesNotEraseFinalizedHistoryEvenSameDay()throws Exception{Long id=id(create(batchId,today,null,admin));save(id,marks("PRESENT","PRESENT","PRESENT","PRESENT"));finish(id);var enrollment=enrollments.findByBatchIdAndStudentIdOrderByEnrollmentDate(batchId,cohort.getFirst().getId()).getFirst();mvc.perform(json(patch("/api/batches/"+batchId+"/enrollments/"+enrollment.getId()+"/withdraw"),Map.of("withdrawalDate",today.toString()),admin)).andExpect(status().isOk());assertThat(enrollments.findEligibleOn(batchId,today)).hasSize(3);mvc.perform(get("/api/attendance/sessions/"+id).header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andExpect(jsonPath("students.length()").value(4));mvc.perform(get("/api/attendance/me").header("Authorization","Bearer "+studentToken)).andExpect(status().isOk()).andExpect(jsonPath("totals.presentCount").value(1));Long newId=id(create(batchId,today,"11:00",admin));mvc.perform(get("/api/attendance/sessions/"+newId).header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andExpect(jsonPath("students.length()").value(3));}
    @Test void withdrawnBeforeClassIsNotEligibleAndStaleDraftRequiresResave()throws Exception{Long id=id(create(batchId,today,null,admin));save(id,marks("PRESENT","PRESENT","PRESENT","PRESENT"));var e=enrollments.findByBatchIdAndStudentIdOrderByEnrollmentDate(batchId,cohort.getFirst().getId()).getFirst();e.setWithdrawalDate(today);e.setStatus(EnrollmentStatus.WITHDRAWN);enrollments.saveAndFlush(e);mvc.perform(post("/api/attendance/sessions/"+id+"/finalize").header("Authorization","Bearer "+admin)).andExpect(status().isConflict());mvc.perform(get("/api/attendance/sessions/"+id).header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andExpect(jsonPath("staleRecords").value(1));mvc.perform(json(put("/api/attendance/sessions/"+id+"/records"),Map.of("version",version(id),"records",marks("PRESENT")),admin)).andExpect(status().isBadRequest());}
    @Test void roleOwnershipAndReportExportSecurity()throws Exception{Long id=id(create(batchId,today,null,admin));for(String token:List.of(otherTeacher,studentToken,parent)){mvc.perform(get("/api/attendance/sessions/"+id).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());mvc.perform(json(post("/api/attendance/sessions"),Map.of("batchId",batchId,"sessionDate",today.toString()),token)).andExpect(status().isForbidden());mvc.perform(json(put("/api/attendance/sessions/"+id+"/records"),Map.of("version",0,"records",List.of()),token)).andExpect(status().isForbidden());mvc.perform(post("/api/attendance/sessions/"+id+"/finalize").header("Authorization","Bearer "+token)).andExpect(status().isForbidden());}
        mvc.perform(get("/api/attendance/me").header("Authorization","Bearer "+studentToken)).andExpect(status().isOk());mvc.perform(get("/api/attendance/students/"+cohort.get(1).getId()+"/summary").header("Authorization","Bearer "+studentToken)).andExpect(status().isForbidden());mvc.perform(get("/api/attendance/students/"+cohort.getFirst().getId()+"/summary").header("Authorization","Bearer "+studentToken)).andExpect(status().isOk());for(String token:List.of(teacherToken,studentToken,parent)){mvc.perform(get("/api/attendance/reports").header("Authorization","Bearer "+token)).andExpect(status().isForbidden());mvc.perform(get("/api/attendance/reports/export").header("Authorization","Bearer "+token)).andExpect(status().isForbidden());}mvc.perform(get("/api/attendance/sessions")).andExpect(status().isUnauthorized());}
    @Test void teacherStudentSummaryOnlyIncludesAssignedBatches()throws Exception{Long own=id(create(batchId,today,null,admin));save(own,marks("PRESENT","PRESENT","PRESENT","PRESENT"));finish(own);Long other=makeBatch("B2");enroll(other,cohort.getFirst(),today.minusDays(2));Long foreign=id(create(other,today,null,admin));save(foreign,marks("ABSENT"));finish(foreign);mvc.perform(get("/api/attendance/students/"+cohort.getFirst().getId()+"/summary").header("Authorization","Bearer "+teacherToken)).andExpect(status().isOk()).andExpect(jsonPath("totals.presentCount").value(1)).andExpect(jsonPath("totals.absentCount").value(0));mvc.perform(get("/api/attendance/sessions").header("Authorization","Bearer "+teacherToken)).andExpect(status().isOk()).andExpect(jsonPath("totalElements").value(1));mvc.perform(get("/api/attendance/batches/"+other+"/summary").header("Authorization","Bearer "+teacherToken)).andExpect(status().isForbidden());}
    @Test void reportsFiltersPaginationAndCsvFormulaEscaping()throws Exception{cohort.getFirst().setFullName("=HYPERLINK(\"evil\")");students.saveAndFlush(cohort.getFirst());Long id=id(create(batchId,today,null,admin));save(id,marks("PRESENT","PRESENT","PRESENT","PRESENT"));finish(id);mvc.perform(get("/api/attendance/reports").param("studentId",cohort.getFirst().getId().toString()).param("size","1").header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andExpect(jsonPath("students.totalElements").value(1)).andExpect(jsonPath("totals.totalEligibleFinalizedSessions").value(1));String csv=mvc.perform(get("/api/attendance/reports/export").param("studentId",cohort.getFirst().getId().toString()).header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8);assertThat(csv).contains("Student name").contains("'=HYPERLINK").contains("\"\"evil\"\"");mvc.perform(get("/api/attendance/reports").param("fromDate",today.toString()).param("toDate",today.minusDays(1).toString()).header("Authorization","Bearer "+admin)).andExpect(status().isBadRequest());mvc.perform(get("/api/attendance/sessions").param("sort","markedBy,desc").header("Authorization","Bearer "+admin)).andExpect(status().isBadRequest());}
    @Test void concurrentSaveAndFinalizeCannotOverwriteFinalizedRecords()throws Exception{Long id=id(create(batchId,today,null,admin));save(id,marks("PRESENT","PRESENT","PRESENT","PRESENT"));long v=version(id);CountDownLatch start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{start.await();return mvc.perform(json(put("/api/attendance/sessions/"+id+"/records"),Map.of("version",v,"records",marks("ABSENT","ABSENT","ABSENT","ABSENT")),admin)).andReturn().getResponse().getStatus();});var b=pool.submit(()->{start.await();return mvc.perform(json(post("/api/attendance/sessions/"+id+"/finalize"),Map.of("version",v),admin)).andReturn().getResponse().getStatus();});start.countDown();assertThat(List.of(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}assertThat(records.count()).isEqualTo(4);}
    @Test void concurrentFinalizationHasExactlyOneWinner()throws Exception{Long id=id(create(batchId,today,null,admin));save(id,marks("PRESENT","PRESENT","PRESENT","PRESENT"));long v=version(id);CountDownLatch start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){List<Future<Integer>> result=new ArrayList<>();for(int i=0;i<2;i++)result.add(pool.submit(()->{start.await();return mvc.perform(json(post("/api/attendance/sessions/"+id+"/finalize"),Map.of("version",v),admin)).andReturn().getResponse().getStatus();}));start.countDown();assertThat(List.of(result.get(0).get(10,TimeUnit.SECONDS),result.get(1).get(10,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}}
    @Test void missingSessionAndUnlinkedStudentHandled()throws Exception{mvc.perform(get("/api/attendance/sessions/999999").header("Authorization","Bearer "+admin)).andExpect(status().isNotFound());cohort.getFirst().setUser(null);students.saveAndFlush(cohort.getFirst());mvc.perform(get("/api/attendance/me").header("Authorization","Bearer "+studentToken)).andExpect(status().isOk()).andExpect(jsonPath("linked").value(false)).andExpect(jsonPath("totals.attendancePercentage").isEmpty());}
}
